using MediatR;using OAS.Application.Abstractions.Persistence;using OAS.Application.Abstractions.Persistence.Specifications;using OAS.Application.Accounting.Abstractions;using OAS.Application.Common.Exceptions;using OAS.Domain.Accounting.Entities;using OAS.Domain.Features.Employees.Entities;
namespace OAS.Application.Accounting.EmployeeAccounts.Commands.ActivateEmployeeAccount;
public sealed class ActivateEmployeeAccountCommandHandler(IRepository<EmployeeAccount,Guid> repository,IReadRepository<Employee,Guid> employees,ILinkedAccountingAccountProvisioningService linkedAccounts):IRequestHandler<ActivateEmployeeAccountCommand,Guid>
{
 public async Task<Guid> Handle(ActivateEmployeeAccountCommand r,CancellationToken ct){var employee=await employees.GetByIdAsync(r.Request.EmployeeId,ct)??throw new NotFoundException(nameof(Employee),r.Request.EmployeeId);if(!employee.IsActive)throw new ConflictException("employee_inactive","Inactive employee cannot be activated for accounting.");var existing=await repository.ListAsync(new Specification<EmployeeAccount>().Where(x=>x.EmployeeId==employee.Id).ApplyPaging(0,1),ct);if(existing.Count>0)throw new ConflictException("employee_account_exists","Employee already has an accounting mapping.");var account=await linkedAccounts.ProvisionEmployeeAccountAsync(employee.DisplayName,r.Request.IsActive,null,ct);var mapping=EmployeeAccount.Create(Guid.NewGuid(),employee.Id,account.Id,r.Request.IsActive);await repository.AddAsync(mapping,ct);return mapping.Id;}
}
